{
  "title": "The Ruined Crown Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team gathers at the broken outer gate.",
      "visual_description": "Four travelers in worn cloaks stand before a shattered stone gate at dawn, faded royal banners drooping above cracked archways.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_walker"]
    },
    {
      "scene_number": 2,
      "caption": "Map reader traces the path inside the ruins.",
      "visual_description": "Close shot of a weathered parchment map spread on a stone block, the map reader pointing toward a sketched tower while the scout leans in.",
      "characters": ["map_reader", "scout"]
    },
    {
      "scene_number": 3,
      "caption": "Frightened townspeople warn of patrols.",
      "visual_description": "A narrow market street with overturned carts; ragged townspeople whisper to the magic helper as armored shapes pass in the background haze.",
      "characters": ["magic_helper", "townsperson_elder", "townsperson_child"]
    },
    {
      "scene_number": 4,
      "caption": "An armored patrol marches past the alley.",
      "visual_description": "Two patrol soldiers in heavy plate stride down a sunlit street; the scout presses flat against a mossy wall just out of view.",
      "characters": ["scout", "patrol_soldier_a", "patrol_soldier_b"]
    },
    {
      "scene_number": 5,
      "caption": "A rumor of dragons drifts through the plaza.",
      "visual_description": "The old plaza with cracked fountain; a hooded rumor monger gestures at smoke curling over distant rooftops while the map reader frowns.",
      "characters": ["map_reader", "rumor_monger"]
    },
    {
      "scene_number": 6,
      "caption": "A sleepy official blocks the inner archway.",
      "visual_description": "A round, yawning official in faded royal livery slouches on a stool under a carved arch, holding a ring of rusty keys.",
      "characters": ["sleepy_official", "magic_helper"]
    },
    {
      "scene_number": 7,
      "caption": "Magic helper charms the keys loose.",
      "visual_description": "Soft blue sparks drift from the magic helper's fingertips toward the official's key ring, which lifts slightly in midair.",
      "characters": ["magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 8,
      "caption": "The team enters the cursed tower courtyard.",
      "visual_description": "A leaning black tower wrapped in pale vines rises over a stone yard; the four travelers stand small at its base, looking up.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_walker"]
    },
    {
      "scene_number": 9,
      "caption": "Cursed tower doors glow with warding runes.",
      "visual_description": "Massive iron-banded doors etched with red glowing sigils; the magic helper raises an open palm, runes reflecting on her face.",
      "characters": ["magic_helper"]
    },
    {
      "scene_number": 10,
      "caption": "Inside the mirror hall, reflections lie.",
      "visual_description": "A long corridor of tall cracked mirrors; the scout sees three different versions of himself stepping out of frame, sword half drawn.",
      "characters": ["scout"]
    },
    {
      "scene_number": 11,
      "caption": "The captive prisoner is found in a chained cell.",
      "visual_description": "A small barred cell deep in the tower; the captive sits chained to a stone bench, looking up as the map reader's lantern light spills in.",
      "characters": ["map_reader", "captive"]
    },
    {
      "scene_number": 12,
      "caption": "Bridge walker steadies the captive on weak stairs.",
      "visual_description": "A spiral staircase missing half its steps; the bridge walker stretches one long arm across the gap, guiding the captive forward.",
      "characters": ["bridge_walker", "captive"]
    },
    {
      "scene_number": 13,
      "caption": "Patrols converge in the tower courtyard.",
      "visual_description": "Four armored patrol soldiers fan out below, torches raised, while the team crouches on a balcony fringed with shattered banners.",
      "characters": ["scout", "captive", "patrol_soldier_a", "patrol_soldier_b", "patrol_captain"]
    },
    {
      "scene_number": 14,
      "caption": "A diversion lights up the old plaza.",
      "visual_description": "The magic helper hurls a flare of green light over the rooftops; soldiers turn toward the glow as the team slips down a side stair.",
      "characters": ["magic_helper", "patrol_captain"]
    },
    {
      "scene_number": 15,
      "caption": "A magic door seals their pursuers behind them.",
      "visual_description": "A heavy stone door grinds shut, glowing seams locking with a snap, the map reader bracing it with both hands as dust rains down.",
      "characters": ["map_reader", "magic_helper", "captive"]
    },
    {
      "scene_number": 16,
      "caption": "The bridge controls lie under tangled roots.",
      "visual_description": "A moss-choked stone gear room with a great rusted lever; the scout pries away vines while the bridge walker reaches for the handle.",
      "characters": ["scout", "bridge_walker"]
    },
    {
      "scene_number": 17,
      "caption": "The escape bridge groans into place.",
      "visual_description": "A long stone bridge over a misty chasm slowly extends from the cliff edge, the rescued captive watching, wind tugging at his torn cloak.",
      "characters": ["bridge_walker", "captive", "map_reader"]
    },
    {
      "scene_number": 18,
      "caption": "The team crosses as the city falls behind.",
      "visual_description": "All five figures walk single file across the narrow bridge into golden mist; the ruined royal city glows red and small in the distance.",
      "characters": ["map_reader", "scout", "magic_helper", "bridge_walker", "captive"]
    }
  ]
}

